from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path

from .audit import audit_text
from .llm import complete, parse_json_object
from .paths import repo_root
from .policy import safe_voice_context

DAILY_CAP = 12


def inbox_path() -> Path:
    path = repo_root() / "inbox" / "queue.jsonl"
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        path.write_text("", encoding="utf-8")
    return path


def add_item(*, url: str, post_text: str, note: str = "") -> dict:
    item = {
        "id": datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ"),
        "url": url,
        "post_text": post_text.strip(),
        "note": note,
        "status": "pending",
        "options": [],
    }
    with inbox_path().open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(item) + "\n")
    return item


def load_inbox() -> list[dict]:
    path = inbox_path()
    items: list[dict] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            items.append(json.loads(line))
    return items


def save_inbox(items: list[dict]) -> None:
    text = "".join(json.dumps(item) + "\n" for item in items)
    inbox_path().write_text(text, encoding="utf-8")


def pending_count_today(items: list[dict]) -> int:
    today = datetime.now(timezone.utc).date().isoformat().replace("-", "")
    return sum(1 for item in items if item.get("id", "").startswith(today) and item.get("status") == "drafted")


def template_options(post_text: str) -> list[dict]:
    snippet = " ".join(post_text.split())[:120]
    return [
        {
            "style": "constraint",
            "text": (
                f"The part I would pressure-test is the failure mode, not the happy path. "
                f"If this cannot fail closed, it is a demo. Re: {snippet}..."
            )[:350],
        },
        {
            "style": "stack",
            "text": (
                "I would keep the model call boring and put the work in ingest, schema, and tenancy. "
                "pgvector without filters is just a junk drawer. Typed outputs beat a clever prompt."
            )[:350],
        },
        {
            "style": "disagree",
            "text": (
                "I would not ship this as a free-text agent. Schema on the way out, human approval "
                "on anything a customer sees. Slower than the demo. That is the point."
            )[:350],
        },
    ]


def llm_options(post_text: str) -> list[dict]:
    raw = complete(
        "Draft LinkedIn comments for Hritik Raj. Use only the safe context. JSON only.\n\n" + safe_voice_context(),
        (
            "Return JSON: {\"options\": [{\"style\": \"constraint|stack|disagree\", \"text\": \"...\"}, ...]}\n"
            "Exactly 3 options, 200-350 characters each. No let's connect. No hashtags.\n\n"
            f"Post:\n{post_text[:3000]}"
        ),
    )
    data = parse_json_object(raw)
    return list(data["options"])


def draft_comments(item_id: str, *, use_llm: bool) -> dict:
    items = load_inbox()
    if pending_count_today(items) >= DAILY_CAP:
        raise RuntimeError(f"Daily comment cap of {DAILY_CAP} reached.")
    for item in items:
        if item["id"] == item_id:
            options = llm_options(item["post_text"]) if use_llm else template_options(item["post_text"])
            cleaned = []
            for option in options:
                text = str(option.get("text") or "").strip()
                result = audit_text(text, slot="b", first_comment="n/a")
                # Slot B length rules do not apply to comments; keep banned-word check only.
                banned = [e for e in result.errors if "Banned" in e or "Bait" in e]
                cleaned.append(
                    {
                        "style": option.get("style"),
                        "text": text,
                        "chars": len(text),
                        "banned": banned,
                    }
                )
            item["options"] = cleaned
            item["status"] = "drafted"
            save_inbox(items)
            return item
    raise KeyError(item_id)
